import React, { useEffect, useState } from "react";
import axios from "axios";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
}) {

  // ================= STATES =================
  const [codes, setCodes] = useState([]);

  // Available Positions
  const positions = [
    "President",
    "Vice President",
    "Secretary",
    "Treasurer",
    "Auditor",
    "Other",
  ];

  const yearLevels = ["1st Year", "2nd Year", "3rd Year", "4th Year"];
  const blocks = ["Block 1", "Block 2", "Block 3"];

  // ================= FETCH VOTER CODES =================
  const fetchCodes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await axios.get("http://localhost:5000/api/admin/codes", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setCodes(res.data);
    } catch (error) {
      console.error("Failed to fetch voter codes");
    }
  };

  useEffect(() => {
    fetchCodes();
  }, []);

  // ================= GENERATE VOTER CODES =================
  const generateCodes = async () => {

  const amount = prompt("How many voter codes do you want to generate?");

    if (!amount) {
    alert("Please enter a number.");
    return;
    }

    if (isNaN(amount)) {
    alert("Amount must be a number.");
    return;
    }

    try {

    const token = localStorage.getItem("token");

    await axios.post(
      "http://localhost:5000/api/admin/generate-codes",
      { amount: Number(amount) },
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );

    fetchCodes();

    alert(`${amount} voter codes generated successfully!`);

  } catch (error) {

    console.error(error);
    alert("Failed to generate voter codes");

  }
};

  // Cancel editing
  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      description: "",
      image: null,
    });
    setEditId(null);
  };

  // Populate form for editing
  const handleEditClick = (c) => {
    setEditId(c._id);
    setCandidateForm({
      firstName: c.firstName,
      lastName: c.lastName,
      candidacy: c.candidacy,
      partylist: c.partylist || "",
      yearLevel: c.yearLevel || "",
      block: c.block || "",
      description: c.description || "",
      image: null,
    });
  };

  return (
    <div
      style={{
        padding: 20,
        borderRadius: 10,
        backgroundColor: theme.card,
        boxShadow: darkModeShadow(theme),
        display: "flex",
        flexDirection: "column",
        gap: 20,
        marginTop: 20,
      }}
    >
      <h3 style={{ color: theme.text }}>
        {editId ? "✏️ Edit Candidate" : "Add Candidate"}
      </h3>

      {/* ================= FORM ================= */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >

        <input
          type="text"
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        <input
          type="text"
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        <select
          value={candidateForm.candidacy}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, candidacy: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Candidacy Position</option>
          {positions.map((pos) => (
            <option key={pos} value={pos}>
              {pos}
            </option>
          ))}
        </select>

        <select
          value={candidateForm.yearLevel || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, yearLevel: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Year Level</option>
          {yearLevels.map((year) => (
            <option key={year} value={year}>
              {year}
            </option>
          ))}
        </select>

        <select
          value={candidateForm.block || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, block: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Block</option>
          {blocks.map((block) => (
            <option key={block} value={block}>
              {block}
            </option>
          ))}
        </select>

        <input
          type="text"
          placeholder="Partylist"
          value={candidateForm.partylist || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, partylist: e.target.value })
          }
          style={inputStyle(theme)}
        />

        <textarea
          placeholder="Description"
          value={candidateForm.description || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, description: e.target.value })
          }
          style={{ ...inputStyle(theme), minHeight: 60 }}
        />

        <input
          type="file"
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, image: e.target.files[0] })
          }
        />

        <div style={{ display: "flex", gap: 10 }}>
          <button type="submit" style={buttonStyle(theme)}>
            {editId ? "Save Changes" : "Add Candidate"}
          </button>

          {editId && (
            <button
              type="button"
              onClick={handleCancelEdit}
              style={cancelButtonStyle}
            >
              Cancel
            </button>
          )}
        </div>
      </form>

      {/* ================= CANDIDATE LIST ================= */}
      <h3 style={{ color: theme.text }}>Current Candidates</h3>

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {candidates.map((c) => (
          <div
            key={c._id}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: 8,
              backgroundColor: "#f0f0f0",
              borderRadius: 6,
            }}
          >
            <span>
              {c.firstName} {c.lastName} ({c.candidacy}) - {c.partylist}
              <br />
              <small>Description: {c.description || "N/A"}</small>
            </span>

            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => handleEditClick(c)} style={editButtonStyle}>
                Edit
              </button>

              <button onClick={() => onDelete(c._id)} style={deleteButtonStyle}>
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* ================= VOTER CODES ================= */}

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h3 style={{ color: theme.text }}>Voter Codes</h3>

        <button
          onClick={generateCodes}
          style={{
            padding: "8px 14px",
            borderRadius: 6,
            border: "none",
            backgroundColor: "#22c55e",
            color: "#fff",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Generate Codes
        </button>
      </div>

      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          backgroundColor: "#f9f9f9",
        }}
      >
        <thead>
          <tr>
            <th style={tableStyle}>Code</th>
            <th style={tableStyle}>Status</th>
          </tr>
        </thead>

        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableStyle}>{c.code}</td>
              <td style={tableStyle}>{c.used ? "Used" : "Unused"}</td>
            </tr>
          ))}
        </tbody>
      </table>

    </div>
  );
}

// ================= STYLES =================

const inputStyle = (theme) => ({
  padding: 8,
  borderRadius: 6,
  border: `1px solid ${theme.text}33`,
  width: "100%",
